static PyObject *py_fish_gbm(PyObject *self, PyObject *args) {
    PyObject *obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    PyObject *fast = PySequence_Fast(obj, "features must be a sequence");
    if (!fast) return NULL;
    if (PySequence_Fast_GET_SIZE(fast) != 18) {
        Py_DECREF(fast);
        PyErr_SetString(PyExc_ValueError, "18 features");
        return NULL;
    }
    double x[18];
    for (int i = 0; i < 18; i++) {
        x[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(fast, i));
        if (x[i] == -1.0 && PyErr_Occurred()) {
            Py_DECREF(fast);
            return NULL;
        }
    }
    Py_DECREF(fast);
    double s = 0.0018105362747059411;
    for (int t = 0; t < 400; t++) {
        int n = FISH_ROOT[t];
        while (!FISH_LEAF[n]) n = x[FISH_FEAT[n]] <= FISH_THR[n] ? FISH_LEFT[n] : FISH_RIGHT[n];
        s += FISH_VAL[n];
    }
    return PyFloat_FromDouble(s);
}

